程序一（Kahn算法）：

```cpp
const int N = 100005;
vector<int> g[N];
int in[N];

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        in[v]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (in[i] == 0) q.push(i);
    int cnt = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cout << u << " ";
        cnt++;
        for (int v : g[u]) {
            in[v]--;
            if (in[v] == 0) q.push(v);
        }
    }
    cout << endl;
    if (cnt < n) cout << "Cycle" << endl;
    return 0;
}
```

设图为有向图，边为 1-2、1-3、2-4、3-4，调用该程序。程序输出的第 2 个整数为 4。（ ）

程序二（DFS判环+拓扑序）：

```cpp
const int N = 100005;
vector<int> g[N];
int vis[N];          // 0 未访问，1 访问中，2 已结束
vector<int> ans;

bool dfs(int u) {
    vis[u] = 1;
    for (int v : g[u]) {
        if (vis[v] == 1) return false;   // 有环
        if (vis[v] == 0) {
            if (!dfs(v)) return false;
        }
    }
    vis[u] = 2;
    ans.push_back(u);
    return true;
}
```

vis 数组用状态 2 表示该顶点已结束（其所有后继顶点均已处理完毕）。（ ）

