参考代码（Kahn 算法判环）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int in[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        in[v]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (in[i] == 0) q.push(i);
    int cnt = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cnt++;
        for (int v : g[u]) {
            in[v]--;
            if (in[v] == 0) q.push(v);
        }
    }
    cout << (cnt == n ? "Yes" : "No") << '\n';
    return 0;
}
```

**原理说明**：入度为 0 的课程无先修，先修完。删去它并更新后继入度，循环往复。若能修完所有课程，输出顶点数等于 n；否则存在循环依赖。复杂度 O(n+m)。

参考代码（小顶堆 Kahn 算法）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int in[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        in[v]++;
    }
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i <= n; i++)
        if (in[i] == 0) pq.push(i);
    vector<int> ans;
    while (!pq.empty()) {
        int u = pq.top(); pq.pop();
        ans.push_back(u);
        for (int v : g[u]) {
            in[v]--;
            if (in[v] == 0) pq.push(v);
        }
    }
    for (int x : ans) cout << x << " ";
    cout << '\n';
    return 0;
}
```

**原理说明**：用优先队列（小顶堆）取代普通队列，每次弹出编号最小的入度为 0 顶点，保证字典序最小。每个顶点进出堆各一次，每条边扫描一次，复杂度 O((n+m)log n)。

参考代码（Kahn 算法判唯一）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int in[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        in[v]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (in[i] == 0) q.push(i);
    if (q.size() > 1) {
        cout << "No\n";
        return 0;
    }
    bool unique = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) {
            in[v]--;
            if (in[v] == 0) q.push(v);
        }
        if (q.size() > 1) unique = false;
    }
    cout << (unique ? "Yes" : "No") << '\n';
    return 0;
}
```

**原理说明**：拓扑排序唯一的充要条件是 Kahn 算法中任一时刻入度为 0 的顶点至多 1 个。若有多个，它们可互换顺序。本题保证无环，无需判环。复杂度 O(n+m)。

参考代码（pos 数组判定）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int pos[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
    }
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        pos[x] = i;
    }
    for (int u = 1; u <= n; u++) {
        for (int v : g[u]) {
            if (pos[u] > pos[v]) {
                cout << "No\n";
                return 0;
            }
        }
    }
    cout << "Yes\n";
    return 0;
}
```

**原理说明**：用 pos 记录每个数字在排列中的位置。对每条边 u→v，只需检查 pos[u] < pos[v] 是否成立；若有违反，则排列不是合法拓扑序列。复杂度 O(n+m)。
